method total_match(lst1: seq<string>, lst2: seq<string>) returns (result: seq<string>)
    requires |lst1| >= 0 && |lst2| >= 0
    ensures (|lst1| == 0 && |lst2| == 0) ==> result == []
    ensures (|lst1| > 0 && |lst2| == 0) ==> result == lst1
    ensures (|lst1| == 0 && |lst2| > 0) ==> result == lst2
    ensures (|lst1| > 0 && |lst2| > 0) ==> 
        (sumChars(lst1) < sumChars(lst2) ==> result == lst1) &&
        (sumChars(lst1) > sumChars(lst2) ==> result == lst2) &&
        (sumChars(lst1) == sumChars(lst2) ==> result == lst1)

method sumChars(lst: seq<string>) returns (total: int)
    requires |lst| >= 0
    ensures total >= 0
    ensures total == sum (s in lst |-> |s|)
{
    total := 0;
    var i := 0;
    while i < |lst|
        invariant 0 <= i <= |lst|
        invariant total == sum (j |-> |lst[j]|) where j in 0 .. i
    {
        total := total + |lst[i]|;
        i := i + 1;
    }
}

